echo json_encode(['estado'=>$codigo===0?'PASS_AGUABAN_RUTA_BD':'BLOQUEADO','casos'=>$casos,'casos_ejecutados'=>count($casos),'aserciones'=>$aserciones,'fuentes'=>$fuentes,'fallo'=>$fallo,'limpieza_confirmada'=>$limpieza,'salida_interna_presente'=>$salida!=='','sql_estricto'=>true,'alcance'=>'CRUD, catálogo ACL, controlador y vistas reales en MariaDB efímera aislada; solo datos ficticios, sin sesiones reales ni PAC.'],JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR),"\n";
exit($codigo);
